import { DatabaseSync } from "node:sqlite";
import { mkdirSync } from "node:fs";
import { dirname } from "node:path";
import { betterAuth } from "better-auth";
import { nextCookies } from "better-auth/next-js";

const dbPath = process.env.DATABASE_PATH ?? "data/notely.db";
mkdirSync(dirname(dbPath), { recursive: true });

export const auth = betterAuth({
  database: new DatabaseSync(dbPath),
  emailAndPassword: {
    enabled: true,
  },
  socialProviders: {
    google: {
      clientId: process.env.GOOGLE_CLIENT_ID as string,
      clientSecret: process.env.GOOGLE_CLIENT_SECRET as string,
    },
  },
  // Must stay last so cookies set inside server actions reach the browser.
  plugins: [nextCookies()],
});
EOF
cat > src/lib/auth-client.ts <<'EOF'
import { createAuthClient } from "better-auth/react";

export const authClient = createAuthClient();
EOF
cat > 'src/app/api/auth/[...all]/route.ts' <<'EOF'
import { toNextJsHandler } from "better-auth/next-js";
import { auth } from "@/lib/auth";

export const { GET, POST } = toNextJsHandler(auth);
EOF
cat > scripts/migrate.ts <<'EOF'
// Creates/updates the Better Auth tables (user, session, account, verification).
// Run with: npm run db:migrate
import { getMigrations } from "better-auth/db/migration";
import { auth } from "../src/lib/auth.ts";

const { toBeCreated, toBeAdded, runMigrations } = await getMigrations(auth.options);

if (toBeCreated.length === 0 && toBeAdded.length === 0) {
  console.log("Database is up to date.");
} else {
  await runMigrations();
  console.log(
    `Migrated: created ${toBeCreated.map((t) => t.table).join(", ") || "none"}; ` +
      `altered ${toBeAdded.map((t) => t.table).join(", ") || "none"}.`,
  );
}
EOF
cat > src/proxy.ts <<'EOF'
import { NextResponse, type NextRequest } from "next/server";
import { getSessionCookie } from "better-auth/cookies";

// Optimistic check only: redirects visitors with no session cookie.
// The real session validation happens in the page via getCurrentUser().
export function proxy(request: NextRequest) {
  if (!getSessionCookie(request)) {
    const url = new URL("/sign-in", request.url);
    url.searchParams.set("next", request.nextUrl.pathname);
    return NextResponse.redirect(url);
  }
  return NextResponse.next();
}

export const config = {
  matcher: ["/dashboard/:path*"],
};
EOF
cat > .env.example <<'EOF'
# Copy to .env.local and fill in real values.

# Secret used to sign session cookies. Generate one with: openssl rand -base64 32
BETTER_AUTH_SECRET=replace-with-a-long-random-string

# Public base URL of the app (used for OAuth callbacks).
BETTER_AUTH_URL=http://localhost:3000

# SQLite database file (created automatically).
DATABASE_PATH=data/notely.db

# Google OAuth — create at https://console.cloud.google.com/apis/credentials
# Authorized redirect URI: http://localhost:3000/api/auth/callback/google
GOOGLE_CLIENT_ID=your-google-client-id.apps.googleusercontent.com
GOOGLE_CLIENT_SECRET=your-google-client-secret
EOF
printf '\n# local database\n/data/\n' >> .gitignore
printf '!.env.example\n' >/dev/null
grep -n "env" .gitignore; grep -n "allowImportingTsExtensions" tsconfig.json

