import "server-only";
import { headers } from "next/headers";
import { auth } from "@/lib/auth";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

type AuthUser = { id: string; email: string; name: string; createdAt: Date };

function toUser(u: AuthUser): User {
  return {
    id: u.id,
    email: u.email,
    name: u.name,
    createdAt: u.createdAt.toISOString().slice(0, 10),
  };
}

async function adapter() {
  return (await auth.$context).adapter;
}

export async function listUsers(): Promise<User[]> {
  const rows = await (await adapter()).findMany<AuthUser>({
    model: "user",
    sortBy: { field: "createdAt", direction: "asc" },
  });
  return rows.map(toUser);
}

export async function getUser(id: string): Promise<User | undefined> {
  const row = await (await adapter()).findOne<AuthUser>({
    model: "user",
    where: [{ field: "id", value: id }],
  });
  return row ? toUser(row) : undefined;
}

// Validates the session cookie against the database. Returns undefined when signed out.
export async function getCurrentUser(): Promise<User | undefined> {
  const session = await auth.api.getSession({ headers: await headers() });
  return session ? toUser(session.user) : undefined;
}
EOF
